const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
const mongoose = require('mongoose');

const SCHOOL_ID = new mongoose.Types.ObjectId('69ce960a98ca4ee738d25416');
const CREATED_BY = new mongoose.Types.ObjectId('69ce960b98ca4ee738d25432');
const GRADE_ID = new mongoose.Types.ObjectId('69d2c1f317b8332733f72601');

let blockNum = 0;
function bid() { return 'block-' + String(++blockNum).padStart(3, '0'); }

function t(order, content) {
  return { blockId: bid(), type: 'text', order, content, points: 0, hints: [], explanation: '', metadata: {}, curriculumNodeId: null, cognitiveLevel: null };
}
function q(order, question, options, correctIndex, explanation, hints) {
  return {
    blockId: bid(), type: 'quiz', order,
    content: JSON.stringify({ question, options, correctIndex }),
    points: 1, hints: hints || [], explanation: explanation || '',
    metadata: { options, correctIndex }, curriculumNodeId: null, cognitiveLevel: null,
  };
}
function fb(order, text, blanks, explanation, hints) {
  return {
    blockId: bid(), type: 'fill_blank', order,
    content: JSON.stringify({ text, blanks }),
    points: blanks.length, hints: hints || [], explanation: explanation || '',
    metadata: { blanks }, curriculumNodeId: null, cognitiveLevel: null,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 1: Development of Self — Healthy Lifestyle (Term 1)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch1_lesson1 = [
  t(1, '## Development of Self: Healthy Lifestyle\n\nAs a Grade 11 learner in South Africa, you are at a stage where your choices about health and lifestyle will shape your future. This chapter explores factors contributing to lifestyle diseases, strategies for prevention, treatment and support, and the long-term benefits of physical engagement.\n\n### What Is a Lifestyle Disease?\n\nA lifestyle disease (also called a non-communicable disease or NCD) is a disease linked mainly to unhealthy behaviours and environmental factors rather than to infections. Examples include cardiovascular disease, type 2 diabetes, certain cancers, and chronic respiratory diseases. In South Africa, NCDs account for more than half of all deaths, making this a critical public health issue.'),
  t(2, '### Factors Contributing to Lifestyle Diseases\n\nSeveral modifiable factors increase the risk of developing lifestyle diseases:\n\n| Factor | Description | SA Context |\n|--------|-------------|------------|\n| **Unhealthy diet** | High intake of processed foods, sugar, salt, saturated fats; low intake of fruits, vegetables, whole grains | Fast-food culture in townships and suburbs, limited access to fresh produce in rural areas |\n| **Physical inactivity** | Sedentary lifestyle, insufficient exercise | Many learners lack safe spaces for physical activity; screen time is increasing |\n| **Tobacco use** | Smoking cigarettes, hookah pipes, e-cigarettes/vaping | SA has high smoking rates; vaping is increasing among youth |\n| **Alcohol and substance abuse** | Excessive alcohol consumption, drug use | SA has one of the highest rates of alcohol-related harm globally |\n| **Unsafe sexual behaviour** | Unprotected sex, multiple partners | Contributes to HIV/AIDS and STIs, which weaken immunity and increase NCD risk |\n| **Stress** | Chronic stress, inadequate coping mechanisms | Poverty, unemployment, violence, and academic pressure are major stressors |'),
  q(3, 'Which of the following is NOT a modifiable factor contributing to lifestyle diseases?',
    ['Genetic predisposition inherited from parents', 'Unhealthy eating habits', 'Lack of physical exercise', 'Tobacco use'], 0,
    'Genetic predisposition is inherited and cannot be changed (non-modifiable). All other options are lifestyle choices that can be modified to reduce disease risk.'),
  t(4, '### Identifying and Defining Lifestyle Diseases\n\nKey lifestyle diseases to know:\n\n**Cardiovascular disease (CVD):** Diseases of the heart and blood vessels, including heart attacks and strokes. Caused by high blood pressure, high cholesterol, smoking, obesity, and physical inactivity.\n\n**Type 2 diabetes:** The body cannot use insulin effectively, leading to high blood sugar. Linked to obesity, poor diet, and inactivity. Increasingly common among young South Africans.\n\n**Cancer:** Abnormal cell growth. Risk factors include smoking (lung cancer), alcohol (liver cancer), poor diet, obesity, and UV exposure (skin cancer). SA has high rates of cervical, breast, and prostate cancer.\n\n**Chronic respiratory diseases:** Asthma, chronic obstructive pulmonary disease (COPD). Worsened by smoking, air pollution, and occupational hazards such as mining dust in SA.'),
  fb(5, 'Diseases linked to unhealthy behaviours rather than infection are called ___ diseases. The inability of the body to use insulin properly leads to type 2 ___.',
    ['lifestyle', 'diabetes'],
    'Lifestyle diseases are caused by modifiable risk factors. Type 2 diabetes results from insulin resistance, often linked to obesity and poor diet.'),
  t(6, '### Discussing the Impact of Lifestyle Diseases\n\nLifestyle diseases have far-reaching consequences:\n\n**On the individual:**\n- Reduced quality of life (pain, fatigue, limited mobility)\n- Shortened life expectancy\n- Financial burden of medication and treatment\n- Mental health impacts (depression, anxiety linked to chronic illness)\n\n**On the family:**\n- Emotional stress of caring for a sick family member\n- Financial strain from medical expenses and loss of income\n- Role reversal where children may become caregivers\n\n**On the community and country:**\n- Increased burden on the public health system\n- Lost productivity and economic output\n- Strain on social grants and welfare systems\n- In SA, the dual burden of infectious diseases (HIV/TB) alongside NCDs overwhelms healthcare facilities'),
  q(7, 'Themba is 16 and eats takeaways daily, never exercises, and spends 6 hours a day on his phone. Which lifestyle diseases is he most at risk of developing?',
    ['Cardiovascular disease and type 2 diabetes', 'Malaria and cholera', 'Tuberculosis and pneumonia', 'Measles and chickenpox'], 0,
    'Unhealthy diet and physical inactivity are primary risk factors for cardiovascular disease and type 2 diabetes. Malaria, cholera, TB, pneumonia, measles and chickenpox are infectious diseases, not lifestyle diseases.'),
  t(8, '### Prevention, Treatment, Care, and Support\n\n**Prevention strategies:**\n- Eat a balanced diet rich in fruits, vegetables, and whole grains\n- Exercise regularly (at least 30 minutes of moderate activity daily)\n- Avoid tobacco and limit alcohol consumption\n- Practise safe sexual behaviour\n- Manage stress through healthy coping mechanisms\n- Get regular health screenings\n\n**Treatment:**\n- Medical treatment prescribed by healthcare professionals\n- Lifestyle changes (diet, exercise) as part of treatment plans\n- Chronic medication for conditions like hypertension and diabetes\n\n**Care and support:**\n- Support groups for people living with chronic diseases\n- Community health workers in SA who provide education and monitoring\n- SADAG (South African Depression and Anxiety Group) for mental health support: 0800 567 567\n- Government clinics offering free chronic medication through the Essential Drug List'),
  t(9, '### Benefits of Long-Term Physical Engagement\n\nRegular physical activity over the long term provides multiple benefits:\n\n| Benefit area | Details |\n|-------------|----------|\n| **Physical health** | Strengthens heart and lungs, improves circulation, maintains healthy weight, builds bone density, boosts immune system |\n| **Mental health** | Reduces stress, anxiety, and depression; releases endorphins (natural mood boosters); improves sleep quality |\n| **Cognitive function** | Improves concentration, memory, and academic performance; increases blood flow to the brain |\n| **Social benefits** | Builds teamwork skills, expands social networks, promotes discipline and commitment |\n| **Disease prevention** | Reduces risk of cardiovascular disease, diabetes, certain cancers, and obesity |\n| **Self-esteem** | Improves body image, builds confidence, provides a sense of achievement |\n\nThe World Health Organisation recommends that adolescents get at least 60 minutes of moderate-to-vigorous physical activity daily.'),
  q(10, 'Which of the following best describes a long-term benefit of regular physical activity?',
    ['Reduced risk of cardiovascular disease and improved mental health', 'Immediate weight loss after one session', 'Guaranteed prevention of all diseases', 'No need to maintain a healthy diet'], 0,
    'Regular physical activity over the long term reduces the risk of CVD, improves mental health through endorphin release, and supports overall well-being. It does not guarantee prevention of all diseases and should be combined with healthy eating.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 2: Relationships (Term 1)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch2_lesson1 = [
  t(1, '## Relationships\n\nRelationships are a fundamental part of human life. As a Grade 11 learner, you are developing more complex relationships and need to understand the dynamics, rights, and responsibilities that come with them.\n\n### Different Types of Relationships\n\nRelationships can be categorised as follows:\n\n| Type | Description | Examples |\n|------|-------------|----------|\n| **Family relationships** | Bonds with family members | Parent-child, sibling, extended family, blended families |\n| **Friendships** | Voluntary bonds based on mutual affection | School friends, neighbourhood friends, online friends |\n| **Romantic relationships** | Intimate bonds involving emotional and sometimes physical closeness | Dating, courtship, marriage |\n| **Professional/Formal** | Relationships within structured environments | Teacher-learner, employer-employee, coach-player |\n| **Community relationships** | Bonds within broader social groups | Neighbours, religious communities, cultural groups |'),
  t(2, '### Rights and Responsibilities in Relationships\n\nEvery relationship involves both rights and responsibilities. The South African Constitution (Bill of Rights, Chapter 2) protects many of these:\n\n**Your rights in relationships:**\n- The right to be treated with dignity and respect (Section 10)\n- The right to privacy (Section 14)\n- The right to freedom and security of the person (Section 12) — no one may abuse you physically or emotionally\n- The right to say no — to physical intimacy, to peer pressure, to any unwanted behaviour\n- The right to equality and non-discrimination (Section 9)\n\n**Your responsibilities in relationships:**\n- Treat others with respect and dignity\n- Communicate honestly and openly\n- Respect boundaries — both your own and others\n- Support and encourage your partner, friends, and family\n- Take responsibility for your actions and their impact on others\n- Seek help when a relationship becomes harmful'),
  q(3, 'Naledi tells her boyfriend that she is not ready for a physical relationship. He pressures her, saying "If you loved me, you would." Which of Naledi\'s constitutional rights is being violated?',
    ['Freedom and security of the person (Section 12)', 'Freedom of expression (Section 16)', 'Freedom of religion (Section 15)', 'Right to education (Section 29)'], 0,
    'Section 12 of the Bill of Rights protects freedom and security of the person, including the right to make decisions about your own body. Pressuring someone into physical intimacy violates this right.'),
  t(4, '### Qualities Sought in Relationships\n\nHealthy relationships are built on key qualities:\n\n**Trust:** Being able to rely on the other person. Trust is built over time through consistent, honest behaviour.\n\n**Respect:** Valuing the other person as an equal, accepting differences, and honouring boundaries.\n\n**Communication:** Sharing thoughts and feelings openly, listening actively, and resolving disagreements constructively.\n\n**Empathy:** Understanding and sharing another person\'s feelings. This requires active listening and suspending judgement.\n\n**Honesty:** Being truthful even when it is difficult. Honesty builds trust and prevents misunderstandings.\n\n**Commitment:** Being willing to invest time and effort into the relationship. This means being there during good times and bad.\n\n**Support:** Encouraging each other\'s goals, dreams, and personal growth.'),
  fb(5, 'The ability to understand and share another person\'s feelings is called ___. The right to make decisions about your own body is protected by Section ___ of the Bill of Rights.',
    ['empathy', '12'],
    'Empathy is the ability to put yourself in someone else\'s shoes. Section 12 of the South African Bill of Rights protects freedom and security of the person.'),
  t(6, '### Detrimental Relationships\n\nNot all relationships are healthy. Detrimental (harmful) relationships include:\n\n**Abusive relationships:**\n- Physical abuse: hitting, slapping, pushing\n- Emotional abuse: insults, manipulation, gaslighting, threats\n- Sexual abuse: any unwanted sexual contact or coercion\n- Financial abuse: controlling someone\'s access to money\n\n**Controlling relationships:**\n- One partner makes all decisions\n- Isolating you from friends and family\n- Monitoring your phone, social media, or movements\n- Using jealousy as an excuse for control\n\n**Toxic friendships:**\n- Friends who consistently bring you down or undermine your confidence\n- Friendships based on peer pressure to engage in risky behaviour\n- One-sided friendships where only one person puts in effort\n\n**Warning signs:** Constant criticism, isolation from loved ones, walking on eggshells, feeling afraid or anxious, loss of self-esteem.'),
  q(7, 'Sipho\'s girlfriend checks his phone daily, gets angry when he spends time with friends, and threatens to break up if he does not reply to messages immediately. This behaviour is an example of:',
    ['A controlling relationship', 'A healthy relationship with high standards', 'Normal teenage jealousy that will pass', 'A sign of deep love and commitment'], 0,
    'Monitoring a partner\'s phone, isolating them from friends, and using threats are hallmarks of a controlling relationship. These behaviours are harmful and should not be normalised as love or caring.'),
  t(8, '### Getting Help for Harmful Relationships\n\nIf you or someone you know is in a harmful relationship:\n\n**Immediate steps:**\n- Talk to a trusted adult (parent, teacher, school counsellor)\n- Contact a helpline:\n  - Childline: 0800 055 555\n  - Stop Gender Violence Helpline: 0800 150 150\n  - Lifeline SA: 0861 322 322\n  - SAPS Emergency: 10111\n\n**Legal protection in SA:**\n- The Domestic Violence Act (Act 116 of 1998) provides for protection orders\n- The Sexual Offences Act protects against sexual abuse and exploitation\n- The Children\'s Act protects children under 18 from abuse and neglect\n\n**Remember:**\n- Abuse is NEVER the victim\'s fault\n- Leaving an abusive relationship takes courage and support\n- It is okay to ask for help — it is a sign of strength, not weakness'),
  t(9, '### Appropriate Expression of Feelings in Relationships\n\nExpressing your feelings appropriately is essential for healthy relationships:\n\n**Using "I" statements:**\n- Instead of: "You never listen to me!" (accusatory)\n- Say: "I feel unheard when I am interrupted" (expresses your feelings without blame)\n\n**Choosing the right time and place:**\n- Do not discuss serious issues in public or when emotions are running high\n- Wait until both parties are calm and have privacy\n\n**Respecting cultural contexts:**\n- In South Africa\'s diverse culture, different communities may have different norms around emotional expression\n- Some cultures emphasise stoicism; others are more openly expressive\n- Understanding these differences prevents misunderstandings\n\n**Healthy expression includes:**\n- Naming your emotions specifically ("I feel disappointed" rather than "I feel bad")\n- Taking responsibility for your feelings\n- Listening to the other person\'s perspective\n- Finding solutions together rather than assigning blame'),
  q(10, 'Which of the following is the best example of appropriately expressing feelings in a relationship?',
    ['"I feel hurt when plans are cancelled without explanation because I value our time together"', '"You always cancel on me — you obviously do not care about me"', '"Whatever, it is fine" (while clearly upset)', '"I am going to tell everyone what you did to me"'], 0,
    'The first option uses an "I" statement, identifies the specific feeling and trigger, and explains why it matters. The other options are accusatory, passive-aggressive, or threatening.'),
];

